int vg_point_validate_id(FAR const char *id)
{
  size_t n;
  size_t i;

  if (id == NULL)
    {
      return 0;
    }

  n = strlen(id);
  if (n < 1 || n > 23)
    {
      return 0;
    }

  for (i = 0; i < n; i++)
    {
      if (!(isalnum((unsigned char)id[i]) || id[i] == '_'))
        {
          return 0;
        }
    }

  return 1;
}

int vg_point_validate_name(FAR const char *name)
{
  size_t n;
  size_t i;
  unsigned char c;

  if (name == NULL)
    {
      return 0;
    }

  n = strlen(name);
  if (n < 1 || n > (VG_POINT_NAME_MAX - 1))
    {
      return 0;
    }

  for (i = 0; i < n; i++)
    {
      c = (unsigned char)name[i];
      if (c <= 0x20 || c == 0x7f || c == '=' || c == '"' || c == '\\')
        {
          return 0;
        }
    }

  return 1;
}

