powershell.exe -ExecutionPolicy Bypass -Command '
$ErrorActionPreference = "Stop"
$port = New-Object System.IO.Ports.SerialPort
$port.PortName = "COM3"
$port.BaudRate = 115200
$port.ReadTimeout = 8000
$port.NewLine = "`n"
function Send-Serial($Port, $Cmd, $WaitSec) {
  $Port.DiscardInBuffer()
  $Port.WriteLine($Cmd)
  Start-Sleep -Milliseconds 400
  $buf = ""
  $deadline = (Get-Date).AddSeconds($WaitSec)
  while ((Get-Date) -lt $deadline) {
    if ($Port.BytesToRead -gt 0) { $buf += $Port.ReadExisting() }
    if ($buf -match "nsh>") { break }
    Start-Sleep -Milliseconds 120
  }
  Write-Output ("`n=== " + $Cmd + " ===`n" + $buf)
  return $buf
}
try {
  $port.Open()
  Start-Sleep -Seconds 10
  $boot = ""
  $bootDeadline = (Get-Date).AddSeconds(20)
  while ((Get-Date) -lt $bootDeadline) {
    if ($port.BytesToRead -gt 0) { $boot += $port.ReadExisting() }
    if ($boot -match "nsh>") { break }
    Start-Sleep -Milliseconds 200
  }
  Write-Output ("=== boot ===`n" + $boot)
  while ($port.BytesToRead -gt 0) { [void]$port.ReadExisting(); Start-Sleep -Milliseconds 50 }
  $list = Send-Serial $port "vgpoint list" 8
  Start-Sleep -Seconds 2
  $get = Send-Serial $port "vgpoint get" 8
  $id = $null
  if ($list -match "id=([A-Za-z0-9_]+)") { $id = $Matches[1] }
  if ($id) {
    Send-Serial $port ("vgpoint get " + $id) 8 | Out-Null
    $get1 = Send-Serial $port ("vgpoint get " + $id) 8
    Write-Output ("first_id=" + $id)
    Write-Output $get1
  }
  $noid = Send-Serial $port "vgpoint get no_such_point_id" 8
  Write-Output $noid
  $all = $list + $get + $noid
  if ($all -match "bus_busy") { Write-Output "[FAIL] bus_busy in get/list"; exit 1 }
  if ($get -match "unknown_verb") { Write-Output "[FAIL] get unknown_verb"; exit 1 }
  if ($get -match "vgpoint: OK cmd=get" -or $get -match "code=no_sample" -or $get -match "code=no_id") {
    Write-Output "[PASS] get replied"
  } else {
    Write-Output "[FAIL] get no OK/ERR"
    exit 1
  }
  if ($noid -match "code=no_id" -or $noid -match "cmd=get table=committed n=0") {
    Write-Output "[PASS] unknown id or empty table"
  }
  Write-Output "[PASS] no bus_busy"
  exit 0
} catch {
  Write-Output ("error: " + $_.Exception.Message)
  exit 1
} finally {
  if ($port.IsOpen) { $port.Close() }
}
'

